#!/usr/bin/python3
"""Controller power/timing/BOM calculations; no measurement or quote claims."""
import json,csv,math,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'hardware/controller';D=P/'review/M6-C1'
VARIANTS={'FOX_MIN':{'ALL','RF80'},'RF80_FULL':{'ALL','RF80'},'RF2M_FULL':{'ALL','RF2M'},'UNIVERSAL':{'ALL','RF80','RF2M'},'UNIVERSAL_LORA_OPEN':{'ALL','RF80','RF2M','LORA_OPTION_OPEN'}}
FOX_OMIT={'U42','C43','R108','R109','R112','R113','R114','R115','R116','R117'}
def fitted_part(part,variant):return part['population'] in VARIANTS[variant] and not(variant=='FOX_MIN' and part['ref'] in FOX_OMIT)
def save(n,x):(D/n).write_text(json.dumps(x,indent=2)+'\n')
def main():
    m=json.loads((P/'CTRL.electrical.json').read_text());parts=[x for x in m['parts'] if not x['ref'].startswith(('#','TP'))]
    fields=['ref','quantity_per_unit','package_review','value','mpn','footprint','population','group','source_url','supplier','supplier_part_number','availability','moq','evidence','price_1_eur','price_10_eur','price_20_eur']
    rows=[]
    def price(p,q):return float(max(((int(k),v) for k,v in p['price_breaks_eur'].items() if int(k)<=q),default=min((int(k),v) for k,v in p['price_breaks_eur'].items()))[1])
    for p in parts:
        row={k:p.get(k,'OPEN') for k in fields if not k.startswith('price_')};row['quantity_per_unit']=1;row['package_review']='OPEN_OPTION_DO_NOT_POPULATE' if p['ref']=='U70' else 'CAD landing selected; see package-and-pad-audit.json; physical fit NOT_RUN';row.update({f'price_{q}_eur':price(p,q) for q in [1,10,20]});rows.append(row)
    with (D/'BOM-all.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=fields,lineterminator="\n");w.writeheader();w.writerows(rows)
    totals={};pop={}
    for variant,groups in VARIANTS.items():
        fitted=[p for p in parts if fitted_part(p,variant)];refs={p['ref'] for p in fitted};pop[variant]=dict(fitted=sorted(refs),DNP=sorted({p['ref'] for p in parts}-refs));totals[variant]={}
        for q in [1,10,20]:
            observed=sum(price(p,q) for p in fitted if p['evidence'].startswith('OBSERVED'));estimated=sum(price(p,q) for p in fitted if not p['evidence'].startswith('OBSERVED'))
            totals[variant][str(q)]={'components_per_unit_net_eur':round(observed+estimated,3),'observed_net_eur':round(observed,3),'estimated_unquoted_net_eur':round(estimated,3),'purchased_parts':len(fitted),'IC_count':sum(p['ref'].startswith('U') for p in fitted),'VAT':'excluded; apply destination rules separately','freight':'OPEN / excluded'}
        with (D/('BOM-'+variant+'.csv')).open('w') as f:
            w=csv.DictWriter(f,fieldnames=fields,lineterminator="\n");w.writeheader();w.writerows(x for x in rows if x['ref'] in refs)
    save('population-variants.json',pop);save('costs.json',{'status':'CANDIDATE ESTIMATES, not purchase quotations','date':'2026-10-18','variants':totals,'bare_PCB_model':{'method':'Unquoted setup4EUR + area0.0001EUR/mm2/board; not JLC quote','area_mm2':10000,'net_batch_eur':{str(q):4+q for q in [5,10,20]},'shipping_net_eur_allowance':[10,25],'standard_stencil_separate_net_estimate_eur':[8,20]},'external_costs_net_estimates':{'CR1220_cell':[.4,1.0],'IDC16_cable150mm':[1.5,3.0],'IDC20_cable150mm':[1.7,3.5],'pack_ID_controller_branch':[1.0,2.0],'fused_RF_harness':[3,7],'M3_standoffs_and_hardware':[.5,1.2]},'excluded':['RF modules','batteries/BMS','charger','enclosure','antenna','assembly and calibration labor'],'LoRa_hold':'Exact ZTR8-GC identity vs distributor TR8-GC not confirmed; euro FX allowance, not EU quote.'})
    budgets={}
    for v in [6,8.4,12,16.8]:
        budgets[str(v)]={'controller_3p3_at_40mA_W':.132,'both_ports_reserved_150mA_each_W':.99,'optional_LoRa_TX_120mA_W':.396,'PACK_PROT_bleed_upper_W':round(v*v/10000,4),'worst_0p92A_output_80pct_input_A':round(3.3*.92/(.8*(v-1.1)),3)}
    save('power-analysis.json',{'classification':'CALCULATED; physical supply tests NOT_RUN','input_range_V':[6,16.8],'regulator':{'MPN':'AP63203WU-7','operating_V':[3.8,32],'absolute_DC_V':35,'absolute_400ms_V':40,'setpoint_V':3.3,'reference_accuracy_percent':1.5,'max_output_IC_electrical_A':2,'normal_steady_controller_design_budget_A':.4,'reserved_burst_A':.92,'inductor_uH':4.7,'switching_Hz':1100000,'ripple_A_at16V':3.3*(1-3.3/16)/(4.7e-6*1.1e6),'Cout_nominal_uF':44,'Cout_effective_design_scenario_uF':17.6,'Cout_effective_status':'44uF nominal;17.6uF scenario=44*0.8tol*0.5bias, not vendor guarantee; vendor curves/bench transient gate OPEN'} ,'logic_rail_interval_V':[3.2505,3.3495],'RF_connector_component_only_minimum_without_copper_V':3.2505-.15*(.088+.08),'final_native_rail_budget':'connector-rail-budget.json','RF_connector_nominal_contract_V':[3.135,3.465],'ADC':{'battery_sense':'PACK_PROT after reverse diode, not raw terminal voltage','divider':[470000,47000],'ratio':1/11,'max_at16p8V':16.8/11,'max_at29p2V_TVS_rating':29.2/11,'diode_drop_uncertainty_V':[.1,.79],'raw_pack_voltage_interval':'[11*Vadc, 11*Vadc+0.79], plus ADC/divider error; no precise fuel gauge claim','settling_ms':25,'module_id_pullup_ohms':33000,'module_ID_ohms':[18200,39200,82000],'module_ID_nominal_V':[3.3*r/(33000+r) for r in [18200,39200,82000]],'PA_rail_ratio':1/13,'power_off_protection':'TMUX1511 inputs <=5.5V with VDD0, no signal above3.6V at MCU during specified rails'},'reset_supervisor':{'MPN':'TLV803EA30DBZR','nominal_threshold_V':3.08,'reset_delay_ms':200,'qualification':'analog ramp/decay and local RF fail-off NOT_RUN'},'rail_budgets':budgets,'thermal_scenarios':{'classification':'CALCULATED / not guaranteed board thermal resistances','AP63203_published_JA_K_W':89,'published_test_board':'single-layer2oz manufacturer fixture, not this1oz board','assumed_conservative_board_JA_K_W':150,'steady3p3_A':.4,'minimum_efficiency_scenario':.8,'buck_loss_W':3.3*.4*(1/.8-1),'buck_Tj_40C_scenario':40+3.3*.4*(1/.8-1)*150,'0p92A_continuous_Tj_scenario_C':40+3.3*.92*(1/.8-1)*150,'policy':'0.92A is a short burst allocation, not permitted continuous current. Normal one selected RF logic port, WiFi/BLE off, LoRa TX off-slot. Measure thermal/ripple before extending budget.','diode_D4_worst_at0p4A_out_6V_in_W':1.1*(3.3*.4/(.8*(6-.79-1.1-.1))),'physical':'NOT_RUN'},'USB':{'limit_resistor_ohms':100000,'approximate_current_limit_A':.3,'supply_path':'USB -> TPS2553 -> STPS1L30A -> buck. BZT52H-B5V1 bounds reverse leakage into USB_LIMIT. No intended USB-to-pack path; pack-present hardware inhibits USB-only RF.', 'minimum_startup_V_calculated':4.4-.395-.03,'AP63203_minimum_operating_V':3.8,'D3_reverse_leak_max_at100C_30V_A':.015,'clamp_at15mA_scenario_V':5.20+60*.01+.0012*75,'clamp_status':'Differential-resistance extrapolation/thermal scenario, not a guaranteed DC clamp curve. Power-only hot reverse-leak test before normal use.', 'VBUS_sense':'GPIO37 inverted Q2 collector; firmware USB PHY detaches when VBUS absent. RTC INT unused, hundredths/time polled over I2C.','physical_gates':['USB enumeration/inrush/current','MCU startup current without WiFi','attach/detach during battery operation']},'reverse_leakage_presence':{'D4':'S1M low leakage; Schottky not used','D4_hot_leakage_assumption_uA':50,'R7_bleeder_ohm':10000,'PACK_PROT_upper_USB_only_V':.5,'Q1_base_upper_V':.25,'status':'calculated component-bound scenario, hot leakage bench gate remains'},'endurance':'Controller-only incremental model. RF module input energy must be measured over selected duty. 12h/24h full system NOT_RUN.'})
    # Incremental controller budget only. M2 cell energy provisions remain
    # unqualified assumptions; no obsolete RF headroom model is imported.
    energy=11.9*.8*.9*.9
    cont=.132/.85
    rows=[]
    for pack,cells in [('2S1P',2),('2S2P',4),('2S3P',6),('2S4P',8),('4S1P',4),('4S2P',8)]:
        usable=energy*cells
        rows.append({'pack':pack,'cells':cells,'usable_Wh_scenario':usable,'average_total_input_W_12h':usable/12,'average_total_input_W_24h':usable/24,'remaining_module_input_W_12h_after_host40mA':usable/12-cont,'remaining_module_input_W_24h_after_host40mA':usable/24-cont})
    save('incremental-endurance.json',{'classification':'CALCULATED planning budgets, not battery endurance results','source':'docs/M2_ENDURANCE_REWORK.md;11.9Wh minimum cell energy times0.8aging*0.9window*0.9temperature','controller_host_40mA_at85pct_W':cont,'port150mA_increment_at85pct_W':3.3*.15/.85,'omitted_losses':'RF loads, presence bleeder, diode drop, actual buck loss, cable/BMS, battery cutoff and optional radio must be added to measured complete-device budget','rows':rows,'classic':'20pct transmit duty may be applied to measured TX and idle loads; power preparation/RTC/driver idle remain included','continuous':'beacon/Fox may be100pct duty; no20pct borrowing','physical':'12h full /24h reduced NOT_RUN'})
    # RC response matches native R4 AM reconstruction values; labels are model predictions.
    fc=1/(2*math.pi*10000*4.7e-9);pwm=80000000/256;tone=800;gain=1/math.sqrt((1-(tone/fc)**2)**2+(tone/(.5*fc))**2)
    save('timing-analysis.json',{'classification':'CALCULATED / host simulation, not MCU physical demonstration','RTC':{'MPN':'RV-3032-C7','temperature_accuracy_ppm':2.5,'first_year_aging_budget_ppm':3,'worst_sum_ppm':5.5,'seconds_per24h_initial':2.5e-6*86400,'seconds_per24h_with_aging':5.5e-6*86400,'initial_sync_budget_s':.25,'daily_total_bound_s':.25+5.5e-6*86400+.01,'hundredths_quantization_allowance_s':.01,'backup':'CR1220 -> BAS116 ->1k -> VBACKUP; BSM10 LSM explicitly programmed, trickle disabled. Verify readback.','physical':'Drift/backup transfer/time-setting accuracy NOT_RUN'},'PWM':{'ESP_clock_Hz':80000000,'channels':2,'shared_LEDC_timer':0,'resolution_bits':8,'carrier_Hz':pwm,'sample_timer_Hz':31250,'sample_period_us':32,'tone_initial_Hz':800,'DDS_frequency_resolution_Hz':31250/(2**32),'AF_and_LEVEL':'LEVEL DC and AF equal offset+sine; KEY selects waveform on RF board. Maintain phase and approximately3ms transition ramps.','RC_filter_fc_Hz':fc,'RC_filter_Q':.5,'tone_gain':gain,'carrier_attenuation_dB_approx':40*math.log10(pwm/fc),'full_scale_step_V':3.3/255,'normal_command_example':{'centre_code':110,'amplitude_code_75pct_unfiltered_example':82,'amplitude_code_75pct_ideal_filter_compensated':round(110*.75/gain),'amplitude_code_80pct_ideal_filter_compensated':round(110*.80/gain),'rail_centre_ideal_V':110/255*3.3*2.8},'reduced_command_example':{'centre_code':61,'amplitude_code_80pct':49},'warning':'Codes are bounded bench starting examples, not RF power or AM calibration. 8bit quantization RMS after2.8gain about10.5mV. ISR/LUT/latency remain target implementation and scope qualification gates.'},'Morse':{'timer_resolution_Hz':1000000,'dit_us_at8WPM':150000,'dit_us_at15WPM':80000,'timer_quantization_us':1,'foundation':'Host SOS edge fixture. Dedicated GPTimer/RMT resources reserved independently of SPI/USB/LoRa.'},'progress':{'GPIO':39,'toggle_interval_ms':25,'same_polarity_edge_interval_ms':50,'complete_waveform_Hz':20,'producer':'Meaningful control-loop progress commit; never autonomous PWM/ISR','RF80_watchdog_bound_ms':250,'RF2M_watchdog_bound_ms':230},'clock_correction':'Freeze active slot deadline in monotonic time. Apply small corrections off-slot; large/invalid time disarms and requires deliberate restart. No wall-clock step may extend an active slot.'})
    print('Costs q10:',{v:x['10']['components_per_unit_net_eur'] for v,x in totals.items()})
if __name__=='__main__':main()
